// 数据表是只读事实来源：冻结后 UI/渲染器无法意外篡改，保证设计确定性。
function deepFreeze(value) {
  if (value && typeof value === "object" && !Object.isFrozen(value)) {
    for (const key of Object.keys(value)) deepFreeze(value[key]);
    Object.freeze(value);
  }
  return value;
}
deepFreeze(CRYSTALS);

export const CRYSTAL_BY_ID = Object.freeze(
  Object.fromEntries(CRYSTALS.map((crystal) => [crystal.id, crystal]))
);

